#!/usr/bin/env python3
"""Audit the presentation actually generated by EqSystem and AugP2 APIs.

This checker deliberately starts below every declared ``Gamma_*`` grammar.
The official EqSystem supplies polynomial variables and one relation cell per
colour word.  The repository's response, cap/AugP2, window and bar APIs then
supply the 128 callable primitives audited elsewhere.  We form the free typed
cellular category on exactly those generators and inspect its operation graph.

Every generator is objectwise.  Hence the generated presentation has no
response-to-cap arrow in degree zero or one and cannot receive the natural
Phi bicomplex.  Adjoining a normalized Phi as a new generator gives the
canonical eight kappa interchanges, but this is a completion of the literal
presentation, not a consequence of EqSystem.  Two completions, one with and
one without an additional bright off-diagonal atom, have identical EqSystem
and implemented cap restrictions.  Thus present source data underdetermine
essential surjectivity.  The bright completion is a logical countermodel, not
an asserted physical GHZ operation.
"""

from __future__ import annotations

import argparse
from fractions import Fraction as Q
from hashlib import sha256
import importlib.util
from itertools import combinations, product
import json
from pathlib import Path
import sys


ROOT = Path(__file__).resolve().parents[1]
PINS = {
    "computations/verify_chart_model_is_official_eqsystem.py":
        "ef1a997323e0a116787fa3c50368e22ecd33804942a9179eabefa2993e4d9373",
    "notes/chart-model-is-the-official-eqsystem.md":
        "dd0c1f5b6233199086a4934ffff8f0ccabf9e6d2badf67fb1c1ce33fa38076ec",
    "computations/verify_h3_gamma_star_executable_gen_phys_registry.py":
        "173ebdedcfdadd9891704223ea93731509c18a4d120aa34d6c7bc8a4f3aebddb",
    "computations/verify_h3_gamma_star_source_derived_free_closure_census.py":
        "a479ac8759bf7a18b43ee91d8b1ab7d0b432c48a7787b065cac68403ace3df3a",
    "computations/verify_h3_response_ks_to_cap_r0_multiplicative_comparison_gate.py":
        "02a28ec54b83b2f786e47b0fdc992f5f28dd95a04ba16219f0e24482d4999097",
    "notes/h3-response-ks-to-cap-r0-multiplicative-comparison-gate.md":
        "b87cccff771337fc7ed6d0092f958303084c1be8326a9faf46efb7fa751ed8f6",
    "computations/verify_h3_shear_collision_augp2_packaging_map_gate.py":
        "bd3f008eb2faf00bbebccb09ef9692908f2e0ae4a795706de2c32f0b2ef342af",
    "computations/verify_h3_direct_free_complete_first_fine_degree_membership.py":
        "190171b72493e661dedb8e7aa369a9b72f1a71e14487632df2841ca7eeb19bf4",
    "notes/h3-direct-free-complete-first-fine-degree-membership.md":
        "be8407215a2435faefc779bab6ef02a7cb256fd8d2aae118ab55ab13934058fc",
    "computations/verify_h3_psi_canonical_source_resolution_degree1_loophole_gate.py":
        "feb162f9d13d6debff78361fd28cada31a61bd9ccd57aab62f2722bf365c5064",
}
EXPECTED_LEDGER_SHA256 = "15c1b6dcb8eb0d34d6efbacfc5f9f03a610a1f8d714286d9e9d87daa87a697d3"

OBJECTS = ("response", "cap", "window", "bar")
KAPPA_WORDS = (
    "0012", "0102", "0110", "0111",
    "0122", "0212", "1112", "2112",
)
DELTA = tuple(map(Q, (1, 1, -1, -1)))
ZERO4 = (Q(0),) * 4


def require(condition: bool, detail: object) -> None:
    if not condition:
        raise RuntimeError(detail)


def load(relative: str, name: str):
    specification = importlib.util.spec_from_file_location(name, ROOT / relative)
    require(specification is not None and specification.loader is not None,
            ("cannot import", relative))
    module = importlib.util.module_from_spec(specification)
    sys.modules[name] = module
    specification.loader.exec_module(module)
    return module


def pin_dependencies() -> None:
    for relative, expected in PINS.items():
        actual = sha256((ROOT / relative).read_bytes()).hexdigest()
        require(actual == expected,
                ("pinned dependency changed", relative, actual, expected))


def dot(left, right) -> Q:
    require(len(left) == len(right), "dot width")
    return sum((Q(a) * Q(b)
                for a, b in zip(left, right, strict=True)), Q(0))


def rank(columns) -> int:
    columns = tuple(tuple(map(Q, column)) for column in columns)
    if not columns:
        return 0
    height = len(columns[0])
    require(all(len(column) == height for column in columns), "rank height")
    rows = [[columns[column][row] for column in range(len(columns))]
            for row in range(height)]
    answer = 0
    for column in range(len(columns)):
        pivot = next((row for row in range(answer, height)
                      if rows[row][column]), None)
        if pivot is None:
            continue
        rows[answer], rows[pivot] = rows[pivot], rows[answer]
        value = rows[answer][column]
        rows[answer] = [entry / value for entry in rows[answer]]
        for row in range(height):
            if row == answer or not rows[row][column]:
                continue
            value = rows[row][column]
            rows[row] = [left - value * right for left, right in
                         zip(rows[row], rows[answer], strict=True)]
        answer += 1
    return answer


def official_eqsystem_presentation_audit(official) -> dict[str, object]:
    vertices = tuple(range(8))
    colours = tuple(range(3))
    variables = tuple(
        (u, v, left, right)
        for u, v in combinations(vertices, 2)
        for left, right in product(colours, repeat=2)
    )
    words = tuple(product(colours, repeat=8))
    matchings = official.OFFICIAL_MATCHINGS
    require(len(variables) == 252 and len(set(variables)) == 252,
            "official variable census changed")
    require(len(words) == 6561
            and sum(len(set(word)) == 1 for word in words) == 3,
            "official word/target census changed")
    require(len(matchings) == 105 and len(set(matchings)) == 105,
            "official matching census changed")
    for matching in matchings:
        require(len(matching) == 4
                and {site for edge in matching for site in edge} == set(vertices),
                ("not a perfect matching", matching))

    # This is the canonical first Tate stage of the literal polynomial
    # presentation.  The relation symbols have a word and polynomial degree,
    # but EqSystem defines no fine/repeated/operation/window idempotents.
    gamma_word = tuple(map(int, "01211222"))
    require(gamma_word in words and len(set(gamma_word)) > 1,
            "Gamma word left the mixed relations")
    return {
        "base_ring": "Q (the census is combinatorial and ring-independent)",
        "canonical_weight_variables": len(variables),
        "variable_formula": "C(8,2)*3^2",
        "relation_cells": len(words),
        "pure_target_relations": 3,
        "mixed_zero_target_relations": len(words) - 3,
        "perfect_matching_monomials_per_relation": len(matchings),
        "total_relation_monomial_occurrences": len(words) * len(matchings),
        "relation_polynomial_degree": 4,
        "first_Tate_stage": (
            "P[e_iota], |e_iota|=1, d(e_iota)=pmSum(iota)-target(iota)"
        ),
        "Gamma_word_relation_cells": 1,
        "literal_labels_present": ["eight-site colour word", "polynomial degree"],
        "literal_labels_absent": [
            "response/cap operation parent", "fine t*q_(v,N)",
            "repeated P3+K2", "window occurrence", "AugP2 face type",
        ],
        "primitive_response_to_cap_operation_defined": False,
        "reason": (
            "EqSystem is a polynomial predicate; it does not define an enriched "
            "operation category or Hom(response,cap)"
        ),
    }


def literal_generated_presentation_audit(source_derived) -> dict[str, object]:
    ledger, digest = source_derived.audit()
    require(digest == source_derived.EXPECTED_LEDGER_SHA256, digest)
    executable = ledger["executable_Gen_phys"]
    closure = ledger["typed_free_closure"]
    require(executable == {
        "constructor_invocations": 128,
        "literal_Gamma_entries": 25,
        "Gamma_image_rank": 23,
        "B_Eq_image_rank": 7,
        "Psi_charge_histogram": {"0": 128},
        "operation_object_counts": {
            "response": 1, "cap": 26, "window": 100, "bar": 1,
        },
        "implemented_operation_changing_atoms": 0,
        "literal_kappa_columns": 0,
    }, executable)
    require(closure["Hom0_response_cap_dimension"] == 0
            and closure["free_closure_operation_changing_C1_count"] == 0
            and closure["mapping_cylinder_on_epsilon_s_r0"] ==
                "MissingPhysicalArrow",
            closure)

    # The free category on loops has only diagonal paths, in every degree.
    primitive_edges = {(name, name) for name in OBJECTS}
    reachable = set(primitive_edges)
    for _ in range(len(OBJECTS)):
        reachable |= {
            (left_source, right_target)
            for left_source, left_target in tuple(reachable)
            for right_source, right_target in tuple(reachable)
            if left_target == right_source
        }
    require(reachable == primitive_edges
            and ("response", "cap") not in reachable,
            reachable)
    return {
        "construction": (
            "free typed cellular category on the official EqSystem relation "
            "cells and every presently callable response/cap/window/bar API"
        ),
        "callable_non_EqSystem_primitives": executable["constructor_invocations"],
        "operation_object_counts": executable["operation_object_counts"],
        "literal_Gamma_cap_entries": executable["literal_Gamma_entries"],
        "Gamma_image_rank_of_callable_registry": executable["Gamma_image_rank"],
        "B_Eq_rank_of_callable_registry": executable["B_Eq_image_rank"],
        "all_callable_Psi_charges": 0,
        "operation_graph_edges": [list(edge) for edge in sorted(reachable)],
        "Hom0_response_cap": 0,
        "primitive_Hom1_response_cap": 0,
        "generated_Hom1_response_cap": 0,
        "literal_kappa_columns": 0,
        "Macaulay_b01_times_cap_r0": (
            "implemented, but cap->cap and literal Gamma mixed projection zero"
        ),
        "attempt_to_build_Phi_mapping_cylinder": "MissingPhysicalArrow",
        "finite_comparison_functor_from_natural_Phi_bicomplex_exists": False,
        "first_undefined_image": "Phi_KS,r0 itself",
        "theorem": (
            "the smallest presentation generated by actual current data is "
            "disconnected; no composition of its generators changes response "
            "to cap"
        ),
    }


def normalized_completion_audit(source_derived) -> dict[str, object]:
    ledger, digest = source_derived.audit()
    require(digest == source_derived.EXPECTED_LEDGER_SHA256, digest)
    completion = ledger["completion_by_missing_Phi"]
    require(tuple(completion["literal_words"]) == KAPPA_WORDS
            and completion["quotient_rank"] == 8
            and completion["Psi_charges"] == ["0"] * 8,
            completion)

    # The four mutually exclusive feature types give the normal form in the
    # freely generated Phi completion.  Only word x K_Eq is off-diagonal and
    # noncanonical, once for each one-root word.
    truth = completion["pairwise_feature_truth_table"]
    require(len(truth) == 4
            and sum(value == "standard kappa interchange"
                    for value in truth.values()) == 1,
            truth)
    basis = tuple(
        tuple(Q(1 if row == column else 0) for row in range(8))
        for column in range(8)
    )
    require(rank(basis) == 8, "the eight word idempotents collapsed")
    return {
        "completion": "P_lit freely adjoin one normalized source-labelled Phi family",
        "new_degree_zero_schema": "Phi_KS,r0: response -> cap",
        "standard_relative_degree_one_words": list(KAPPA_WORDS),
        "normal_form_quotient_basis": "eight word x K_Eq interchanges",
        "quotient_rank_modulo_canonical_and_chi_dark": rank(basis),
        "strict_B_Eq_boundaries": "(v_i,v_i)",
        "normalized_Psi_charges": [0] * 8,
        "finite_comparison_functor": (
            "the natural Phi bicomplex is isomorphic to this freely adjoined "
            "off-diagonal subcategory, by generator and four-feature normal form"
        ),
        "source_status": (
            "conditional completion: Phi and its proper physical faces are not "
            "generators of P_lit"
        ),
    }


def two_completion_counterguard() -> dict[str, object]:
    # Quotient coordinates remember only the eight standard word idempotents
    # and, in the second completion, one independent off-diagonal identity.
    standard = tuple(
        tuple(Q(1 if row == column else 0) for row in range(9))
        for column in range(8)
    )
    omega = (Q(0),) * 8 + (Q(1),)
    require(rank(standard) == 8 and rank(standard + (omega,)) == 9,
            "completion quotient ranks changed")
    psi = DELTA + tuple(-value for value in DELTA)
    bright_boundary = DELTA + ZERO4
    require(dot(psi, bright_boundary) == 4,
            "bright completion stopped being detected")
    return {
        "common_restriction": (
            "the official 252 variables, 6561 relations, and all 128 callable "
            "constructor outputs/differentials"
        ),
        "completion_A": {
            "name": "P_Phi",
            "relative_quotient_rank": rank(standard),
            "generators": "the eight standard kappa interchanges",
            "all_normalized_Psi_charges": 0,
        },
        "completion_B": {
            "name": "P_Phi+omega",
            "relative_quotient_rank": rank(standard + (omega,)),
            "extra_generator": "omega_0102: response -> cap, degree one",
            "canonical_EqSystem_and_callable_constructor_shadow": 0,
            "B_Eq_boundary": "(delta,0)",
            "external_target_q_anchor_ores_W_ridge_shadow": 0,
            "chi": 4,
        },
        "restrictions_are_identical": True,
        "logical_consequence": (
            "EqSystem plus the currently encoded cap/AugP2 constructors cannot "
            "imply essential surjectivity onto the eight kappas"
        ),
        "physicality_guard": (
            "omega is an admissible enriched-presentation completion, not an "
            "asserted source-provenant GHZ operation"
        ),
    }


def terminal_audit(psi_gate) -> dict[str, object]:
    ledger, digest = psi_gate.audit()
    require(digest == psi_gate.EXPECTED_LEDGER_SHA256, digest)
    terminal = ledger["mapping_cone_and_physical_terminal"]
    required = terminal["accepted_Fredholm_requires"]
    require(len(required) == 4
            and terminal["physical_q_status"]["q_or_anchor_detects_the_missing_class"]
                is False,
            terminal)
    return {
        "callable_Gamma_map": "rank 23/27; B/Eq rank 7/8; Psi kills all 128 entries",
        "accepted_terminal_now": False,
        "why_not": [
            "the exhaustive physical off-diagonal comparison domain is absent",
            "the literal physical RHS/candidate is not identified in that codomain",
            "Phi proper target/q/anchor/residue/W/ridge faces are not constructed",
        ],
        "accepted_Macaulay_Fredholm_requirements": required,
        "conditional_promotion": (
            "if P_phys,Gamma is proved equal to P_Phi, with the literal RHS in "
            "the same fully augmented codomain, normalized Psi kills the "
            "exhaustive map and pairs one with the RHS; only then does the "
            "existing kernel-generator/Fredholm alternative apply"
        ),
        "countercompletion_effect": (
            "omega raises B/Eq rank 7 to 8 and fills the local class, so Psi "
            "does not descend to a terminal in completion B"
        ),
    }


def audit() -> tuple[dict[str, object], str]:
    pin_dependencies()
    official = load(
        "computations/verify_chart_model_is_official_eqsystem.py",
        "actual_presentation_official_eqsystem",
    )
    source_derived = load(
        "computations/verify_h3_gamma_star_source_derived_free_closure_census.py",
        "actual_presentation_source_derived",
    )
    psi_gate = load(
        "computations/verify_h3_psi_canonical_source_resolution_degree1_loophole_gate.py",
        "actual_presentation_psi_gate",
    )

    ledger = {
        "theorem": "h3 EqSystem/AugP2 literal-presentation underdetermination gate",
        "pins": PINS,
        "official_EqSystem_first_presentation":
            official_eqsystem_presentation_audit(official),
        "smallest_literal_generated_presentation":
            literal_generated_presentation_audit(source_derived),
        "normalized_Phi_completion": normalized_completion_audit(source_derived),
        "two_completion_counterguard": two_completion_counterguard(),
        "Macaulay_Fredholm_terminal": terminal_audit(psi_gate),
        "verdict": (
            "The actual presentation generated by the official EqSystem cells "
            "and all callable cap/AugP2 APIs is operation-disconnected and has "
            "Hom^1(response,cap)=0; it does not even contain Phi or a kappa. "
            "Freely adjoining normalized Phi gives an exact finite comparison "
            "whose relative quotient is the eight dark kappas, but an equally "
            "compatible completion can adjoin a ninth bright atom. Therefore "
            "the present literal data do not determine essential surjectivity. "
            "No actual physical exotic was found; the exact missing datum is a "
            "source-labelled enriched comparison/minimality theorem for Phi and "
            "all off-diagonal degree-one primitives, followed by the literal "
            "fully augmented RHS comparison required for Fredholm promotion."
        ),
        "scope": (
            "exact official N=8,D=3 EqSystem generator census, exact callable "
            "h=3 constructor registry/free closure, and exact rational two-"
            "completion counterguard.  This is not a full decorated-source "
            "presentation and does not assert the bright completion is physical."
        ),
    }
    digest = sha256(json.dumps(
        ledger, sort_keys=True, separators=(",", ":")
    ).encode()).hexdigest()
    if EXPECTED_LEDGER_SHA256 != "TO_BE_PINNED":
        require(digest == EXPECTED_LEDGER_SHA256,
                ("actual-presentation ledger changed", digest))
    return ledger, digest


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--mode", choices=(
        "all", "eqsystem", "literal", "completion", "terminal",
    ), default="all")
    parser.add_argument("--json", action="store_true")
    arguments = parser.parse_args()
    ledger, digest = audit()
    if arguments.json:
        print(json.dumps({"mode": arguments.mode, "ledger": ledger,
                          "sha256": digest}, indent=2, sort_keys=True))
    else:
        print(f"h3 EqSystem/AugP2 actual-presentation gate ({arguments.mode}): PASS")
        print("literal generated Hom^1(response,cap): 0; Phi/kappa: absent")
        print("free Phi completion: eight dark kappas; exotic completion: rank 9")
        print("actual physical essential surjectivity: UNDERDETERMINED")
        print("accepted Macaulay/Fredholm terminal: NOT YET")
        print("ledger_sha256=" + digest)


if __name__ == "__main__":
    main()
